// Fold the health response and the alert destination into one item.
//
// A request that failed outright (Vercel down, DNS gone) arrives here with no
// status field. That is an outage too, and defaulting it to healthy would make
// this monitor the silent failure it exists to prevent — so anything that is
// not an explicit 'healthy' counts as degraded.
const health = $input.first()?.json ?? {};
const config = $('Load config').first()?.json ?? {};

const status = health.status === 'healthy' ? 'healthy' : 'degraded';
const summary =
  health.summary || health.error || 'no response from /api/health — the app itself may be down';

return [
  {
    json: {
      status,
      summary,
      drain_age_s: health.drain_age_s ?? null,
      oldest_waiting_s: health.oldest_waiting_s ?? null,
      dead_rows: health.dead_rows ?? null,
      checked_at: health.checked_at ?? new Date().toISOString(),
      webhook: config.alert_webhook_url || '',
      text: `:rotating_light: LexHive delivery degraded — ${summary}`,
    },
  },
];
